  const pathname = usePathname();
  const menuRef = useRef<HTMLDivElement>(null);
  const isInitialMenuRender = useRef(true);

  useEffect(() => {
    if (menuRef.current) {
      if (menuOpen) {
        gsap.to(menuRef.current, { yPercent: 0, duration: 0.6, ease: 'power3.inOut' });
      } else {
        if (!isInitialMenuRender.current) {
          gsap.to(menuRef.current, { yPercent: 100, duration: 0.8, ease: 'power3.inOut' });
        } else {
          gsap.set(menuRef.current, { yPercent: 100 });
          isInitialMenuRender.current = false;
        }
      }
    }
  }, [menuOpen]);

  useEffect(() => {
    const handleScroll = () => {
      setIsScrolled(window.scrollY > 40);

      // Hide header when within 150px of the bottom end of the page (the footer)
      const threshold = 150;
      const isAtBottom = window.innerHeight + window.scrollY >= document.documentElement.scrollHeight - threshold;
      setIsHidden(isAtBottom);
    };
    window.addEventListener('scroll', handleScroll);
    return () => window.removeEventListener('scroll', handleScroll);
  }, []);

  useEffect(() => {
    if (menuOpen) {
      document.body.style.overflow = 'hidden';
    } else {
      document.body.style.overflow = '';
    }
    return () => { document.body.style.overflow = ''; };
  }, [menuOpen]);

  // Ensure menu closes automatically when route changes
